<style>
#Page { width: stretch; height: stretch; }
#Cells { display: grid; width: stretch; grid-template-columns: repeat(auto-fill, minmax(calc(var(--size-xxl) * 4.4), 1fr)); gap: var(--space-lg); padding: var(--space-lg); }
.cell { display: flex; flex-direction: column; gap: var(--space-xs); min-width: 0; }
.cell[data-member=selection], .cell[data-member=commands], .cell[data-member=resources] { grid-column: span 2; }
.caption { font: var(--text-caption); color: var(--ink-muted); }
.stage { display: flex; min-width: 0; align-items: flex-start; padding: var(--space-sm); border-radius: var(--radius-sm); background: var(--well); }
@media (width < 600px) {
  #Cells { grid-template-columns: minmax(0, 1fr); padding: var(--space-sm); gap: var(--space-md); }
  .cell[data-member=selection], .cell[data-member=commands], .cell[data-member=resources] { grid-column: span 1; }
}
</style>
